import{_ as i,c as a,o as e,ae as r}from"./chunks/framework.Dh1jimFm.js";const b=JSON.parse('{"title":"Changelog ADMC","description":"","frontmatter":{},"headers":[],"relativePath":"projects/admc/changelog/index.md","filePath":"projects/admc/changelog/index.md"}'),o={name:"projects/admc/changelog/index.md"};function t(h,l,n,u,d,s){return e(),a("div",null,l[0]||(l[0]=[r('<h1 id="changelog-admc" tabindex="-1">Changelog ADMC <a class="header-anchor" href="#changelog-admc" aria-label="Permalink to &quot;Changelog ADMC&quot;">​</a></h1><h2 id="официальныи-журнал-изменении-проекта-находится-по-адресу" tabindex="-1">Официальный журнал изменений проекта находится по адресу: <a class="header-anchor" href="#официальныи-журнал-изменении-проекта-находится-по-адресу" aria-label="Permalink to &quot;Официальный журнал изменений проекта находится по адресу:&quot;">​</a></h2><ul><li><a href="https://github.com/altlinux/admc/blob/master/CHANGELOG_ru.txt" target="_blank" rel="noreferrer">Admc сhangelog на русском языке</a></li><li><a href="https://github.com/altlinux/admc/blob/master/CHANGELOG.txt" target="_blank" rel="noreferrer">Admc сhangelog на английском языке</a></li></ul><h2 id="версия-0-10-0" tabindex="-1">ВЕРСИЯ 0.10.0 <a class="header-anchor" href="#версия-0-10-0" aria-label="Permalink to &quot;ВЕРСИЯ 0.10.0&quot;">​</a></h2><ul><li>Свойства: Удалена вкладка «Группа». Она больше не нужна, поскольку её заменяет дерево политик.</li><li>Политики: Улучшено отображение дерева политик. Теперь вместе с политиками в нём расположены подразделения (OU). Подразделения отображают подразделения своих потомков и связанные политики. Возможность просмотра всех политик сохраняется в папке «Все политики».</li><li>Разное: Исправлен неполный просмотр длинных элементов в области видимости. Корректное отображение полосы прокрутки в области видимости теперь обеспечивает возможность полного просмотра элементов.</li><li>Разное: Добавлено удаление лишних пробелов в строке имени, выполняемое при создании или переименовании политик, папок запроса и элементов запроса.</li><li>Разное: Исправлена ошибка, где объект становился незагруженным, если в ходе переименования в его имя вставлялся символ «?».</li><li>Разное: Увеличен размер поля атрибутов строки на вкладке «Атрибуты». Теперь легче просматривать и редактировать длинные строки.</li><li>Разное: Удалена возможность перетаскивания политик на дерево объектов подразделения. Данное действие теперь выполняется внутри дерева политик.</li></ul><h2 id="версия-0-9-0" tabindex="-1">ВЕРСИЯ 0.9.0 <a class="header-anchor" href="#версия-0-9-0" aria-label="Permalink to &quot;ВЕРСИЯ 0.9.0&quot;">​</a></h2><ul><li>Вкладка «Учётная запись»: Исправлено поле параметра &quot;Время входа&quot;.</li><li>Вкладка «Учётная запись»: Исправлена ошибка вывода пустого значения поля «Компьютеры для входа в систему» при открытии.</li><li>Вкладка «Учётная запись»: Исправлено неверное значение флага параметра учётной записи «Обратимое шифрование».</li><li>Вкладка «Атрибуты»: Добавлен специальный формат отображения некоторых атрибутов битовых полей, позволяющий корректно выводить как имена, так и значения битовых полей. Включает «userAccountControl», «sAMAccountType» и «primaryGroupId».</li><li>Вкладка «Учётная запись»: Добавлен отсутствующий параметр учётной записи «Ключ DES».</li><li>Вкладка «Учётная запись»: Удалён параметр «Доверять делегирование», поскольку он должен находиться только на вкладке «Делегирование».</li><li>Вкладка «Учётная запись»: Исправлено несколько параметров, которые используют некорректные флаги.</li><li>Меню «Действие»: Расширено количество создаваемых типов объектов: «Контакт», «inetOrgPerson» и «Общая папка».</li><li>Меню «Действие»: В меню «Действие» откорректировано подменю «Новое». Теперь оно содержит только те объекты, которые могут быть потомками целевого объекта. (#343)</li><li>Меню «Действие»: У объектов компьютера удалено действие «Переименовать», поскольку переименование объектов компьютера должно проводится самой машиной в конфигурации системы.</li><li>Консоль: Добавлен параметр ограничения отображения объекта. Применяется к главному окну и диалоговому окну поиска. (#319)</li><li>Вкладка «Адрес»: В целях удобства использования изменён порядок вывода списка стран, чтобы страна текущей региональной настройки всегда отображалась в начале списка.</li><li>Консоль: Реализовано открытие меню действий по щелчку на свободном пространстве панели результатов. При этом выделенный элемент области рассматривается в качестве целевого объекта меню. (#334)</li><li>Консоль: Исправлен вывод пустого меню действий при запуске пока пользователь не выбрал другой элемент консоли. (#340)</li><li>Консоль: Исправлена способность перемещения объекта на своего текущего родителя посредством меню действий или перетаскивания. Ранее это вызывало проблемы с отображением. (#336, #338)</li><li>Консоль: Улучшен способ сортировки вывода результатов по умолчанию (для всех типов представления - Значки, Список, Подробно).</li><li>Создание диалогового окна: Исправлены некорректные подписи полей.</li><li>Время входа: Улучшено удобство использования.</li><li>Время входа: Добавлен текст пояснения по работе диалогового окна.</li><li>Вкладка «Безопасность»: Добавлена обработка наследуемых прав. Наследуемые права теперь правильно отображаются в виде недоступных для редактирования неактивных флажков. (#327)</li><li>Вкладка «Безопасность»: Исправлено некорректное отображение одинаковых прав у всех объектов. На вкладке «Безопасность» теперь корректно отображаются права, соответствующие типу объекта. (#328)</li><li>Вкладка «Безопасность»: Добавлена проверка порядка ACL. При переключении на вкладку «Безопасность», порядок будет проверяться и в случае его некорректности будет выводиться диалоговое окно предупреждения с предложением исправить порядок. (#339)</li><li>Панель инструментов: Для всех действий добавлены комбинации клавиш.</li><li>Свойства: Добавлена вкладка LAPS (Диспетчер паролей локальных администраторов) для объектов компьютера. Эта панель будет доступна только при наличии LAPS в домене. (#312)</li><li>Свойства: Исправлена реакция диалогового окна свойств на сбой загрузки пользователя в связи с ошибкой соединения или отсутствии объекта.</li><li>Свойства: Отключена вкладка «Профиль», в связи с невозможностью использования, так как реализация данной функции в серверном модуле отсутствует.</li><li>Свойства: Отключена функция «Компьютеры для входа в систему», в связи с невозможностью использования, так как реализация данной функции в серверном модуле отсутствует.</li><li>Политики: Исправлено неверное указание на ошибки в политиках, созданных с помощью RSAT, при проверке разрешений. (#333)</li><li>Политики: Для политик добавлено действие «Редактировать». Для правильной работы необходима установка пакета «gpui».</li><li>Запросы: Из корня «Запросы» удалены действия «Вырезать» и «Копировать», в связи с тем, что данные действия применить к нему невозможно. (#350)</li><li>Запросы: Удалена возможность рекурсивно вырезать и вставлять папки запроса друг в друга.</li><li>Запросы: Устранено зависание программы при копировании и вставке папки в саму себя.</li><li>Запросы: Исправлено имя по умолчанию для папок запроса при создании.</li><li>Запросы: Устранена ошибка копирования и вставки папки запроса в того же родителя.</li><li>Запросы: Удаление возможности перетаскивания папок запроса в самих себя.</li><li>Диалоговое окно поиска: Добавлено фильтрование по всем классам, реализованное в виде отдельного флажка. Фильтрование будет принимать все классы, а не только те, которые включены в список. (#341)</li><li>Элементы управления на вкладке: Устранена ошибка на вкладке, в связи с которой не сохранялись внесённые изменения.</li><li>Элементы управления на вкладке: Исправлены некоторые поля, которые позволяли изменять значения, не предназначенные для изменения.</li><li>Панель меню: Исправлены флажки для типов представления (Значки, Список, Подробно), которые не были исключительными. (#329)</li><li>Панель меню: Устранена ошибка журналирования поиска, сейчас всё исправно работает при обзоре дерева объектов, в диалоговом окне поиска и других элементах интерфейса пользователя.</li><li>Панель меню: Добавлены сочетания клавиш для всех действий, за исключением меню «Действия».</li><li>Панель меню: Добавлены сочетания клавиш для навигации во всех подменю, за исключением меню «Действия».</li><li>Разное: Устранена ошибка фильтрации по классам, которая работала неправильно до открытия диалогового окна выбора класса. Ошибка возникала в диалоговом окне поиска, при создании/редактировании запроса и других подобных случаях. (#322)</li><li>Разное: Добавлено диалоговое окно «Мастера Операций» для просмотра и редактирования FSMO-ролей. Открывается в Меню-&gt;Файл-&gt;Мастера Операций. (#313)</li><li>Разное: Диалоговые окна сообщений об ошибках АД изменены на модальные.</li><li>Разное: Удалена кнопка «Сброс» из диалоговых окон для переименования.</li><li>Разное: Исправлена ошибка значков групп, которые не отображались на некоторых элементах. (#330)</li><li>Разное: Добавлен значок приложения, отображаемый рядом с приложениями в списке и в заголовке окна.</li><li>Разное: Исключена возможность ввода пустого пароля.</li><li>Разное: Исправлено неверное ограничение на длину поля «Имя для входа (до Windows 2000)».</li><li>Разное: Улучшена обработка недопустимых символов в диалоговых окнах создания и переименования объектов.</li><li>Разное: Добавлено автоматическое удаление пробелов в начале и конце имени для большинства полей вставки строковых значений.</li><li>Разное: Исправлено создание объектов компьютера в части правильной установки атрибутов.</li><li>Разное: Добавлена галочка «Показать пароль» для всех полей ввода паролей, обеспечивающая переключение видимости пароля при вводе.</li><li>Разное: Устранена ошибка сбоя программы, которая иногда имела место при загрузке объектов с сервера.</li><li>Разное: Исправлено некорректное поле «Улица» для объектов подразделений. Использовался неверный атрибут.</li><li>Разное: Улучшен перевод.</li></ul><hr><h2 id="версия-0-8-0" tabindex="-1">ВЕРСИЯ 0.8.0 <a class="header-anchor" href="#версия-0-8-0" aria-label="Permalink to &quot;ВЕРСИЯ 0.8.0&quot;">​</a></h2><ul><li>Соединение: Добавлено новое окно, которое выводится в случае сбоя приложения во время запуска при соединении с доменом. Это окно содержит параметры соединения и метод установки повторного соединения. Удалено действие «Соединить» из меню главного окна.</li><li>Консоль: Удалено отображение текущего контроллера домена в поле домена. Теперь оно отображается в параметрах соединения.</li><li>Консоль: Устранена ошибка наложения объекта при получении/обновлении. Это происходило при обновлении объекта в процессе загрузки его потомков. (#290)</li><li>Консоль: Устранена ошибка восстановления состояния результатов. Состояние сохранялось, но иногда происходил сбой при восстановлении. Включает такие настраиваемые параметры, как отображаемые колонки и сортировка. (#299)</li><li>Панель меню: Устранена ошибка сохранения настраиваемого фильтра в диалоговом окне «Фильтровать объекты».</li><li>Панель меню: Удалено меню «Навигация» ввиду неудобства использования. Действия по навигации доступны и значительно более удобно выполняются из панели меню.</li><li>Панель меню: Добавлен вариант просмотра журнала изменений в приложении. Открывается из меню «Помощь».</li><li>Панель меню: Руководство теперь открывается в виде Интернет-версии на wiki.</li><li>Меню «Действие»: Улучшен порядок действий.</li><li>Диалоговое окно поиска: Устранена ошибка выполнения действий с объектами в результатах поиска, например, объекты, остающиеся в результатах поиска после удаления. (#296)</li><li>Диалоговое окно поиска: В диалоговое окно поиска добавлены отсутствующие действия меню «Вид» («Значки», «Список», «Подробно»).</li><li>Диалоговое окно поиска: В диалоговое окно поиска, открываемое из диалогового окна выбора объектов, добавлено меню «Вид».</li><li>Диалоговое окно поиска: Реализована синхронизация изменений, выполняемых в диалоговом окне «Поиск», с главным окном. Например, удаление объекта в диалоговом окне поиска приведёт к удалению его в консоли главного окна. (#298)</li><li>Диалоговое окно поиска: Добавлена кнопка «Очистить» для сброса параметров фильтра и всех результатов. (#314)</li><li>Диалоговое окно поиска: Реализовано обновление объектов в диалоговом окне поиска после перемещения/переименования объектов.</li><li>Диалоговое окно выбора объекта: Добавлена кнопка «Очистить» для сброса параметров фильтра и всех результатов. (#314)</li><li>Запросы: Добавлено состояние «устаревшее» для запросов. На такое состояние запроса указывает изменение значка и подсказки. Запросы становятся устаревшими при переименовании или перемещении их дочерних объектов.</li><li>Запросы: Устранено сохранение объектов дерева запросов в файл параметров, которое приводит к необоснованному увеличению размера файла. Данное исправление также ускоряет завершение работы приложения. (#300)</li><li>Запросы: Добавлена возможность вставки/копирования/вставки нескольких элементов запроса и/или папок.</li><li>Политики: Добавлены «Свойства» для политик в дереве политик. Содержит информацию по политикам, а также вкладку «Безопасность». (#278)</li><li>Свойства: Устранена ошибка синхронизации изменений, внесённых на других вкладках, со вкладкой «Атрибуты» после их применения. Например, изменение поля «Описание» в общей вкладке теперь приводит к его обновлению на вкладке «Атрибуты». (#306)</li><li>Элементы управления на вкладке: Внесено исправление в недоступные поля «Другие». Кнопка теперь активна и открывает дочернее диалоговое окно, доступное только для чтения. (#311)</li><li>Вкладка «Учётная запись»: Исправлено некорректное поведение параметра учётной записи «Делегирование невозможно», при котором активировался параметр «Доверять делегирование». Также исправлены ошибки отображения состояния для этих параметров. (#305)</li><li>Разное: Добавлено расширение для имён по умолчанию при создании политик и папок запросов. Ранее был только один вариант по умолчанию, теперь предлагаются пронумерованные варианты в зависимости от уже существующих настроек. (#302)</li><li>Разное: Действия по переключению элементов пользовательского интерфейса перемещены из меню «Настройки» в меню «Вид».</li><li>Разное: Устранён сбой/зависание программы при входе в качестве непривилегированного пользователя. (#301)</li><li>Разное: Добавлено отображение текущего логина в строке состояния (например, <a href="mailto:username@domain.com" target="_blank" rel="noreferrer">username@domain.com</a>).</li><li>Разное: Устранено некорректное отображение действий «Включить»/«Отключить» для объектов пользователей. Ранее действие «Отключить» отображалось для пользователей, которые уже были отключены. (#297)</li><li>Разное: Устранена ошибка в диалоговом окне ввода пароля, вследствие которой не всегда применялся параметр «Истёк срок действия пароля». (#304)</li><li>Разное: Устранено переполнение буфера на 32-разрядных системах. (#294)</li><li>Разное: Устранён сбой при создании пользователя, имя которого имеет пробелы в начале или в конце слова, при включенном параметре «Пользователь должен сменить пароль». Также была исправлена похожая проблема, возникавшая при создании подразделений и переименовании пользователей. (#308)</li><li>Разное: Функция «Сменить контроллер домена» была перемещена в параметры соединения.</li></ul><hr><h2 id="версия-0-7-0" tabindex="-1">ВЕРСИЯ 0.7.0 <a class="header-anchor" href="#версия-0-7-0" aria-label="Permalink to &quot;ВЕРСИЯ 0.7.0&quot;">​</a></h2><ul><li>Руководство: Устранена ошибка при которой руководство пользователя не открывалось сразу после установки приложения. (#267)</li><li>Руководство: Улучшен метод выбора страниц справки. Сейчас выбор осуществляется однократным щелчком мыши, а также с помощью клавиш со стрелками.</li><li>Политики: Устранена ошибка, при которой на вкладке групповой политики не отображались политики, созданные в Windows. (#270)</li><li>Политики: Исправлен вывод приложением строк gplink в некорректном регистре. Сейчас регистр применяется в том стиле, который принят в Windows. (#271)</li><li>Политики: Добавлено отображение недопустимых связей объектов групповой политики (GPO) на вкладке «Групповая политика». Недопустимые связи могут появится по причине медленной репликации недавно созданных или удалённых GPO, а также вследствие некорректного удаления GPO без удаления связи. (#274)</li><li>Политики: Устранено удаление политик без удаления связей. (#273)</li><li>Политики: Исправлены некорректные разрешения шаблона групповой политики (GPT) для создания политик. (#269)</li><li>Политики: Устранено некорректное удаление GPT (файлы групповой политики на общем ресурсе sysvol). (#277)</li><li>Политики: Добавлена проверка несовпадения разрешений GPO. При наличии несовпадения пользователю выводится предупреждение и предлагается синхронизировать разрешения. (#281)</li><li>Политики: В дереве политик добавлено действие «Обновить». (#279)</li><li>Свойства: Вкладка «Безопасность» добавлена в свойства всех необходимых объектов, не только пользователей.</li><li>Вкладка «Объект»: Добавлена функция «Защитить от удаления», которая позволяет включать или отключать защиту от удаления для объектов. Доступна на вкладке «Объект» или в диалоговом окне создания подразделений. (#283)</li><li>Разное: Добавлена панель инструментов. (#257)</li></ul><hr><h2 id="версия-0-6-4" tabindex="-1">ВЕРСИЯ 0.6.4 <a class="header-anchor" href="#версия-0-6-4" aria-label="Permalink to &quot;ВЕРСИЯ 0.6.4&quot;">​</a></h2><ul><li>Запросы: Исправлена некорректная загрузка состояния в диалоговом окне редактирования запроса, где некоторые поля выводились пустыми. (#255)</li><li>Политики: Устранена ошибка, вследствие которой не закрывалось диалоговое окно создания политики. (#264)</li><li>Политики: Устранена ошибка, вследствие которой не отображались ошибки в диалоговом окне создания политики.</li><li>Политики: Устранена проблема с некорректной загрузкой состояния связи (принудительно/отключено) в составе результатов применения политики, вместо которого всё время загружалась пустая строка. (#263)</li><li>Политики: Исправлена ошибка выполнения действий по удалению, в результате которых файлы GPO не удалялись на sysvol.</li><li>Политики: Временно отключено присвоение дескрипторов безопасности политики файлам на sysvol. На данный момент, файлы вновь создаваемых gpo на sysvol получают дескриптор безопасности по умолчанию. Это происходит в связи с тем, что текущий процесс установки дескрипторов безопасности работает с ошибками.</li><li>Разное: Устранена проблема с заголовками диалоговых окон.</li><li>Разное: Добавлен вывод числа объектов в поле описания у запросов. (#256)</li><li>Панель меню: Добавлены комбинации клавиш для навигации и завершения работы. (#262)</li></ul><hr><h2 id="версия-0-6-3" tabindex="-1">ВЕРСИЯ 0.6.3 <a class="header-anchor" href="#версия-0-6-3" aria-label="Permalink to &quot;ВЕРСИЯ 0.6.3&quot;">​</a></h2><ul><li>Разное: Добавлено руководство пользователя, сформированное на основе wiki. (#218)</li></ul><hr><h2 id="версия-0-6-2" tabindex="-1">ВЕРСИЯ 0.6.2 <a class="header-anchor" href="#версия-0-6-2" aria-label="Permalink to &quot;ВЕРСИЯ 0.6.2&quot;">​</a></h2><ul><li>Консоль: Добавлено действие «Сбросить учётную запись» для объектов компьютера. (#245)</li><li>Консоль: Устранена ошибка параметра «Дополнительные возможности», вследствие которой дополнительные объекты отображались при отключенном параметре. (#247)</li><li>Интерфейс пользователя: Реализовано сохранение и восстановление состояния и геометрии элементов пользовательского интерфейса. Размеры диалогового окна, настройка внешнего вида колонок и их ширина. (#242)</li><li>Параметры: В меню «Файл» добавлены параметры подключения. (#248)</li><li>Разное: Устранён сбой, происходивший в процессе загрузки при отсутствии билетов Kerberos. (#246)</li><li>Разное: Устранён сбой, происходивший в процессе многопоточного поиска при возникновении ошибки соединения. (#249)</li><li>Разное: Исправлено некорректное сообщение об ошибке, выводившееся при наличии конфликтов в параметрах учётной записи. Сообщение содержало некорректные или пустые строки параметров учётной записи. (#251)</li><li>Разное: Устранена ошибка некорректного исправления конфликтующих параметров учётной записи. Установка конфликтующего параметра учётной записи была возможна после закрытия сообщения об ошибке. (#252)</li><li>Разное: Исправлено некорректное поведение при редактировании времени действия в некоторых часовых поясах. При этом дата могла выставляться на следующий день. (#253)</li></ul><hr><h2 id="версия-0-6-1" tabindex="-1">ВЕРСИЯ 0.6.1 <a class="header-anchor" href="#версия-0-6-1" aria-label="Permalink to &quot;ВЕРСИЯ 0.6.1&quot;">​</a></h2><ul><li>Меню «Действие»: Добавлены действия «Включить учётную запись» и «Отключить учётную запись» для объектов компьютера. (#236)</li><li>Консоль: Устранена ошибка, вследствие которой объекты, создаваемые в объекте домена, не добавлялись в консоль. Также устранена похожая ошибка, связанная с перемещением объектов в объект домена. (#240)</li><li>Консоль: Устранена ошибка, вследствие которой на панели результатов всегда отображались все колонки. Сейчас не отображаемые по умолчанию колонки скрываются в соответствии с логикой работы программы. (#237)</li><li>Консоль: Исправлена ошибка обновления объекта в запросах при изменении его свойств.(#241)</li><li>Диалоговое окно «Переименовать»: В версии пользователя поле редактирования UPN было обновлено до повсеместно используемой новой версии. (#238)</li><li>Разное: Улучшен текст в подписях, заголовках и сообщениях.</li><li>Разное: Устранена ошибка, вследствие которой диалоговое окно журнала ошибок не закрывалось при нажатии на кнопку «Закрыть». (#235)</li><li>Разное: Устранена ошибка вывода пустых текстовых строк в некоторых окнах сообщений. (#234)</li><li>Разное: Устранён сбой, возникавший при выполнении действий с объектами, такими как удаление, когда папка «Сохранённые запросы» была пуста. (#239)</li><li>Разное: Добавлен файл .desktop для включения приложения в список приложений. (#231)</li></ul><hr><h2 id="версия-0-6-0" tabindex="-1">ВЕРСИЯ 0.6.0 <a class="header-anchor" href="#версия-0-6-0" aria-label="Permalink to &quot;ВЕРСИЯ 0.6.0&quot;">​</a></h2><ul><li>Диалоговое окно «Свойства»: Применён более эффективный способ обработки сбоя соединения. Диалоговое окно остаётся открытым и отображает информативное сообщение об ошибке.</li><li>Диалоговое окно «Свойства»: Немного увеличена скорость открытия диалогового окна и применения изменений.</li><li>Диалоговое окно «Руководство»: Исправлен путь к руководству пользователя, благодаря чему оно теперь загружается корректно.</li><li>Соединение: Устранён сбой при ошибке получения доменного имени.</li><li>Соединение: Изменён метод определения доменного имени. Если раньше для определения доменного имени использовался домен по умолчанию, то сейчас определение имени происходит с использованием учётной записи по умолчанию. Доменное имя по умолчанию указывается вручную и доступность его не может быть гарантирована.</li><li>Консоль: Отключена возможности открытия контекстного меню щелчком по пустому пространству на панели результатов.</li><li>Консоль: Изменён способ определения целевого объекта для меню «Действие». Если панель результатов активна, но элементы на ней не выделены, то используется текущая область выделения.</li><li>Меню «Действие»: Меню «Создать» становится неактивным при отключении всех действий.</li><li>Меню «Действие»: Не допускается отключение действий у элементов, по которым ещё не получена информация, поскольку это нарушает логику работы контекстного меню.</li><li>Меню «Действие»: Действие «Добавить в группу» доступно для групп. Теперь группы могут добавляться в группы.</li><li>Диалоговое окно выбора объекта: Содержимое основного диалогового окна было изменено с целью применения более простого метода поиска. Расширенные возможности поиска остались доступны в другом диалоговом окне, которое можно открыть с помощью кнопки «Продвинутый».</li><li>Диалоговое окно выбора объекта: Для большей информативности изменены колонки списка выбранных объектов.</li><li>Вкладка «Учётная запись»: Добавлено поле для редактирования значения «Время входа». Обратите внимание на то, что в данный момент эта функция работает только на клиентских приложениях Windows. Для поддержки этой функции на клиентских приложениях Linux, она должна быть реализована в серверном модуле (не в ADMC).</li><li>Вкладка «Учётная запись»: Добавлено поле для редактирования значения параметра «Компьютеры для входа в систему».</li><li>Интерфейс пользователя: Оптимизировано расположение кнопок.</li><li>Интерфейс пользователя: В некоторые диалоговые окна добавлены отсутствовавшие кнопки «Отмена».</li><li>Вкладка «Безопасность»: Реализовано дополнение известных доверенных лиц.</li></ul><hr><h2 id="версия-0-5-3" tabindex="-1">ВЕРСИЯ 0.5.3 <a class="header-anchor" href="#версия-0-5-3" aria-label="Permalink to &quot;ВЕРСИЯ 0.5.3&quot;">​</a></h2><ul><li>Диалоговое окно свойств: Для объектов пользователя добавлена новая вкладка «Безопасность».</li><li>Диалоговое окно свойств: Для объектов компьютера добавлены новые вкладки: «Делегирование», «Руководство», «Группы» и «Операционная система».</li><li>Диалоговое окно свойств: В основную вкладку объектов компьютера добавлено поле «Местонахождение».</li><li>Диалоговое окно создания пользователя: Добавлен параметр «Пользователь не может изменить пароль».</li><li>Фильтры: В диалоговом окне выбора класса удалена кнопка «Отмена».</li><li>Фильтры: Удалена недокументированная возможность, которая при выборе всех классов в фильтре по факту меняла настройки фильтра таким образом, что позволяла принимать ВСЕ классы, включая те, которые отсутствуют в списке классов.</li><li>Диалоговое окно фильтра консоли: Добавлены новые параметры фильтра. Теперь параметры фильтра позволяют: показывать все объекты, показывать выбранные классы и применять настраиваемый фильтр.</li><li>Консоль: Реализовано получение информации по объектам домена и запросам в отдельном потоке.</li><li>Диалоговое окно создания запроса: Устранена ошибка, вследствие которой не выполнялся сброс диалогового окна между несколькими экземплярами программы.</li><li>Диалоговое окно создания запроса: Исправлена подстановка пустого значения в качестве основы для поиска по умолчанию. Теперь в качестве основы для поиска по умолчанию будет использоваться домен, как в диалоговом окне поиска.</li><li>Запросы: К элементам запроса добавлено действие «Редактировать», доступ к которому осуществляется из меню действий.</li><li>Ошибки: Добавлены более информативные сообщения об ошибках, возникающих в процессе подключения.</li></ul><hr><h2 id="версия-0-5-2" tabindex="-1">ВЕРСИЯ 0.5.2 <a class="header-anchor" href="#версия-0-5-2" aria-label="Permalink to &quot;ВЕРСИЯ 0.5.2&quot;">​</a></h2><ul><li>Перевод: Исправлена ошибка загрузки перевода меню «Действие».</li><li>Свойства: Добавлено новое диалоговое окно свойств для нескольких объектов, позволяющее одновременно редактировать свойства нескольких объектов.</li><li>Журнал сообщений: Добавлен параметр для отображения операций поиска LDAP.</li><li>Журнал сообщений: Добавлен параметр для отображения меток времени после сообщений.</li></ul><hr><h2 id="версия-0-5-1" tabindex="-1">ВЕРСИЯ 0.5.1 <a class="header-anchor" href="#версия-0-5-1" aria-label="Permalink to &quot;ВЕРСИЯ 0.5.1&quot;">​</a></h2><ul><li>Консоль: Устранена ошибка, возникавшая в процессе перемещения или удаления элементов при котором некоторые элементы пропускались.</li><li>Диалоговое окно выбора: Устранена ошибка, вследствие которой нажатие клавиши ВВОД вызывало закрытие диалогового окна поиска. Теперь нажатие клавиши ВВОД вызывает нажатие кнопки «Поиск».</li></ul><hr><h2 id="версия-0-5-0" tabindex="-1">ВЕРСИЯ 0.5.0 <a class="header-anchor" href="#версия-0-5-0" aria-label="Permalink to &quot;ВЕРСИЯ 0.5.0&quot;">​</a></h2><ul><li>Консоль: Добавлено новое дерево под названием «Объекты групповой политики», в которое выводятся все политики домена. При выборе политики в панели результатов отображаются все её связи.</li><li>Консоль: Добавлено новое дерево под названием «Сохранённые запросы». Оно состоит из папок, содержащих «запросы». В запросах сохраняется поиск с отображением результатов поиска в панели результатов.</li><li>Консоль: Добавлено отображение текущего контроллера домена в составе подписи элемента домена.</li><li>Консоль: Добавлен дополнительный метод, позволяющий «активировать» элементы панели результатов путём выбора и нажатия клавиши ВВОД. Ранее это можно было сделать только двойным щелчком мыши. Активировать, означает переключить область выделения на выбранный элемент результатов или открыть его свойства.</li><li>Консоль: Реализована сортировка элементов панели результатов.</li><li>Консоль: Реализована регистронезависимая сортировка в области выделения и на панели результатов.</li><li>Меню «Действие»: К объектам домена добавлено действие «Редактировать суффиксы UPN». Открывает меню редактирования суффиксов upn для данного домена.</li><li>Вкладка «Учётная запись»: Добавлено поле со списком, содержащее текущие суффиксы upn, для логина пользователя.</li><li>Вкладка «Атрибуты»: При закрытии программы запоминаются выбранные атрибуты фильтров.</li><li>Диалоговое окно перемещения объекта: Реализована сортировка элементов.</li><li>Вкладка «Атрибуты»: Предотвращается смешивание изменений на вкладке «Атрибуты» с изменениями на других вкладках. Переключение с/на вкладку «Атрибуты» при наличии изменений на вкладках приводит к выводу диалогового окна, которое принуждает пользователя применить или отменить эти изменения.</li><li>Диалоговое окно «Создать»: Добавлено поле со списком, содержащее текущие суффиксы upn, для логина пользователя.</li><li>Меню «Вид»: Добавлены новые варианты просмотра результатов: Значки, Список, Подробно.</li><li>Меню «Вид»: Добавлен параметр «Настроить колонки». Открывает диалоговое окно, позволяющее показывать или скрывать колонки на панели результатов.</li><li>Настройки: Добавлены переключатели для некоторых виджетов консоли. Заменяет «диалоговое окно переключателей виджетов».</li><li>Журнал сообщений: Преобразован в закреплённый виджет. Теперь он может размещаться по сторонам или в нижней части окна. Также возможно произвольное перемещение.</li><li>Диалоговое окно поиска: Устранено продолжительное время ожидания закрытия диалогового окна поиска при наличии большого количества объектов и сортировке их пользователем.</li><li>Диалоговое окно поиска: Исправлено некорректное отображение области и типа группы. Всегда отображались область и тип по умолчанию (Distribution Group - Global).</li><li>Свойства: Добавлена новая вкладка «Руководство», отображаемая у подразделений.</li><li>Свойства: Добавлена новая вкладка «Групповая политика» для отображения и редактирования политик, связанных с выбранным объектом.</li><li>Руководство: Добавлено оглавление и индекс. Однако реального содержимого пока нет.</li><li>Разное: Отключена возможность перетаскивания объектов, перемещение которых невозможно. Раньше такие объекты можно было начать перетаскивать, но по факту переместить их куда-либо не получалось, что приводило к путанице.</li></ul><hr><h2 id="версия-0-4-1" tabindex="-1">ВЕРСИЯ 0.4.1 <a class="header-anchor" href="#версия-0-4-1" aria-label="Permalink to &quot;ВЕРСИЯ 0.4.1&quot;">​</a></h2><ul><li>Свойства: Исправлена ошибка, в результате которой кнопки «Применить»/«Сбросить» становились неактивными при возникновении сбоя в процессе применения изменений. Теперь при возникновении ошибок эти кнопки остаются активными.</li><li>Свойства: Исправлено применение старых изменений на полях и вкладках, если ранее они были применены в том же самом диалоговом окне «Свойства».</li><li>Вкладка «Группы/Участники»: Добавлена возможность выделения основных объектов. Если какие-либо из выделенных объектов являются основными, то при нажатии кнопки «Удалить» выводится предупреждение, а операция удаления не выполняется.</li><li>Вкладка «Группы»: Добавлено отображение элемента «Основная группа».</li><li>Консоль: Внесены изменения в процесс перетаскивания, обуславливающие отсутствие обращений к серверу при выполнении этого действия. Процесс перетаскивания теперь будет выполняться более гладко.</li><li>Диалоговое окно поиска: Процесс поиска перенесён в отдельный поток, что устраняет проблемы с зависанием.</li><li>Диалоговое окно поиска: Устранён сбой приложения при закрытии диалогового окна во время выполнения поискового запроса.</li><li>Диалоговое окно поиска: Удалено ограничение на количество результатов.</li><li>Диалоговое окно поиска: Удалена функция быстрого поиска по причине неудовлетворительной работы.</li><li>Разное: Реализовано рекурсивное удаление, позволяющее удалять объекты вместе с потомками. Раньше это действие вызывало ошибку сервера.</li><li>Разное: Устранена ошибка разрыва соединения при простое. Сейчас приложение устанавливает новое соединение с сервером для каждого набора операций вместо постоянного подключения к одному соединению.</li><li>Разное: Добавлен вывод сообщения с предупреждением об ошибке подключения после попытки выполнения некоторых операций, требующих его наличия.</li></ul><hr><h2 id="версия-0-4-0" tabindex="-1">ВЕРСИЯ 0.4.0 <a class="header-anchor" href="#версия-0-4-0" aria-label="Permalink to &quot;ВЕРСИЯ 0.4.0&quot;">​</a></h2><ul><li>Свойства: в диалоговое окно свойств добавлены вкладки: <ul><li>общее</li><li>объект</li><li>учётная запись</li><li>адрес</li><li>организация</li><li>телефоны</li><li>профиль</li><li>участники</li><li>группы</li></ul></li><li>Свойства: Из закреплённого виджета «Свойства» преобразованы в диалоговое окно.</li><li>Свойства: Заголовки вкладок теперь отображаются в вертикальном списке слева от содержимого вкладки.</li><li>Свойства: «Сведения» переименованы в «Свойства».</li><li>Вкладка «Атрибуты»: Добавлены новые функции: <ul><li>фильтр</li><li>колонка типа атрибута</li><li>специализированные поля для редактирования всех типов атрибутов</li></ul></li><li>Меню «Объект»: Добавлена большая часть действий для работы с объектами.</li><li>Меню «Объект»: Реализовано выполнение действий над несколькими объектами. Для этого выбирается несколько объектов и для всех этих объектов открывается меню. Позволяет перемещать, удалять, переименовывать, а также выполнять другие операции, в зависимости от выделяемых объектов.</li><li>Меню «Объект»: Для более высокой доступности добавлено в панель меню.</li><li>Меню «Объект»: Добавлено несколько диалоговых окон: <ul><li>диалоговое окно «Переименование»</li><li>диалоговое окно «Поиск»</li><li>диалоговое окно «Создание»</li><li>диалоговое окно «Выбор»</li></ul></li><li>Параметры: Добавлены настройки: <ul><li>показывать/скрывать виджеты</li><li>показывать в виджете для контейнеров объекты, не являющиеся контейнерами</li></ul></li><li>Параметры: Добавлено фильтрование виджета «Содержимое»</li><li>Панель меню: Добавлено меню навигации.</li><li>Производительность: Уменьшено время зависания при работе с большим количеством (тысячами) объектов</li><li>Разное: Удалено диалоговое окно входа в систему. Новая схема использования ещё до запуска приложения проводит проверку подлинности на основе kerberos с использованием «kinit», после чего приложение запускается. Также существует вариант попытки подключения после запуска приложения.</li><li>Разное: Реализовано отображение индикатора занятости вместо указателя курсора при выполнении длительных операций.</li><li>Разное: Реализована корректная модальность всех диалоговых окон.</li><li>Разное: Подобраны более подходящие значки объектов.</li><li>Разное: Включена сортировка списка для большинства объектов.</li><li>Разное: Оптимизирована ширина колонок по умолчанию для списков объектов.</li><li>Разное: Реализовано сохранение ширины колонок для следующих сеансов работы приложения.</li></ul>',46)]))}const m=i(o,[["render",t]]);export{b as __pageData,m as default};
